}
void sum(int a, int b) { ... }
void sum(double a, double b) { ... }
int fact(int n) {
if (n == 0) return 1;
return n * fact(n - 1);
}
String s = "Hello";
int len = s.length();
s.toUpperCase();
s.toLowerCase();
s.indexOf("l");
s.contains("He");

Math Class
s.equals("Hello");
s.equalsIgnoreCase("hello");
s.substring(0, 3); // "Hel"
s.replace("H", "J");
Math.max(5, 10);
Math.min(5, 10);
Math.sqrt(16);
Math.pow(2, 3);
Math.abs(-10);
Math.random(); // [0.0, 1.0)

